def raptorJoinIDMJ[T](raster: JavaRDD[ITile[T]], vector: JavaPairRDD[java.lang.Long, IFeature], opts: BeastOptions)
      : JavaPairRDD[java.lang.Long, T] = {
    implicit val ctagK: ClassTag[T] = ClassTag.AnyRef.asInstanceOf[ClassTag[T]]
    JavaPairRDD.fromRDD(raptorJoinIDM[T](raster.rdd, vector.rdd.map(p => (p._1.longValue(), p._2)), opts)
      .map(p => (java.lang.Long.valueOf(p._1), p._2)))
  }

def raptorJoinFeatureJ[T](raster: JavaRDD[ITile[T]], features: JavaRDD[IFeature], opts: BeastOptions):
      JavaRDD[RaptorJoinFeature[T]] = {
    JavaRDD.fromRDD(raptorJoinFeature[T](raster, features.rdd, opts, null))
  }

def raptorJoinIDFullJ[T](raster: JavaRDD[ITile[T]], vector: JavaPairRDD[java.lang.Long, IFeature], opts: BeastOptions):
    JavaRDD[RaptorJoinResult[T]] = {
    JavaRDD.fromRDD(raptorJoinIDFull[T](raster.rdd, vector.rdd.map(x => (x._1.longValue(), x._2)), opts, null))
  }

def raptorJoinLocalJ[T](rasters: Array[IRasterReader[T]], geometries: Array[Geometry]):
      java.util.Iterator[RaptorJoinResult[T]] = {
    import scala.collection.JavaConverters._
    raptorJoinLocal(rasters, geometries).asJava
  }

def raptorJoinLocalJ[T](rasters: Array[IRasterReader[T]], features: Array[IFeature]):
    java.util.Iterator[RaptorJoinFeature[T]] = {
    import scala.collection.JavaConverters._
    raptorJoinLocal(rasters, features).asJava
  }

def geoTiff[T](path: String, iLayer: Int = 0, opts: BeastOptions = new BeastOptions): RDD[ITile[T]] = {
      if (!opts.contains(IRasterReader.RasterLayerID))
        opts.set(IRasterReader.RasterLayerID, iLayer)
      new RasterFileRDD[T](sc, path, opts)
    }

def hdfFile(path: String, layer: String, opts: BeastOptions = new BeastOptions()): RDD[ITile[Float]] = {
      opts.set(IRasterReader.RasterLayerID, layer)
      new RasterFileRDD(sc, path, opts)
    }

def raptorJoin(features: SpatialRDD, opts: BeastOptions = new BeastOptions)(implicit t: ClassTag[T]):
      RDD[RaptorJoinFeature[T]] =
      RaptorJoin.raptorJoinFeature[T](raster, features, opts, null)

def retile[T: ClassTag](raster: RasterRDD[T], tileWidth: Int, tileHeight: Int): RasterRDD[T] = {
    // Notice that for retile, there is a one-to-one correspondence in pixels so we use the more efficient NN method
    reshapeNN(raster, _.retile(tileWidth, tileHeight))
  }

def addTile(tile: ITile[T]): Unit = {
    inputTiles.append(tile)
  }

def printUsage(out: PrintWriter): Unit = {
    out.println("zs <vector file> <raster file> layer:<layer> collector:<collector>")
  }

public int getNumIntersections() {
    return ys.size();
  }

@Override
  public Iterator<Intersection> iterator() {
    return new Iter();
  }

public AffineTransform getModelTransformation() {
        if (metadata != null) return metadata.getModelTransformation();
        return null;
    }

public GeoKeyEntry[] getGeoKeys() {
        return metadata != null
                ? metadata.getGeoKeys().toArray(new GeoKeyEntry[metadata.getGeoKeys().size()])
                : null;
    }

public GeoKeyEntry getGeoKeyRecord(int keyID) {
        return geoKeys.get(keyID);
    }

public Collection<GeoKeyEntry> getGeoKeys() {
        return geoKeys.values();
    }

public void compute(Geometry[] geometries, RasterMetadata metadata) {
    long[] featureIDs = new long[geometries.length];
    for (int i = 0; i < geometries.length; i++)
      featureIDs[i] = i;
    compute(geometries, featureIDs, metadata);
  }

public void compute(ArrayList<Long> IDs, Geometry[] geometries, RasterMetadata metadata) {
    long[] featureIDs = new long[IDs.size()];
    for (int i = 0; i < geometries.length; i++)
      featureIDs[i] = IDs.get(i);
    compute(geometries, featureIDs, metadata);
  }

@Override
  public Iterator<TilePixelRange> iterator() {
    return new PixelRangeIterator();
  }

public double[] getData() {
    return (double[])this.values.clone();
  }

public int hashCode() {
    return Utilities.deepHashCode(this.values);
  }
